 rank:[["Grains ou moulu, pur arabica, bio","Un seul ingrédient ; le bio limite les résidus de pesticides."],["Capsules et dosettes de café pur","Même café, plus d'emballage."],["Café soluble pur","Pratique ; contient plus d'acrylamide que le café torréfié (repères UE : 850 contre 400 µg/kg)."]],
 last:["Cappuccino et « 3 en 1 » en sachet, boissons au café aromatisées","Sucre, sirop de glucose, graisses végétales, arômes : le café est minoritaire."],
